1	package integration
2	
3	import (
4		"bytes"
5		"fmt"
6		"io"
7		"net"
8		"net/http"
9		"net/http/httptrace"
10		"net/textproto"
11		"strings"
12		"sync"
13		"testing"
14		"time"
15	
16		"github.com/caddyserver/caddy/v2/caddytest"
17	)
18	
19	// recordedRequest captures what an upstream actually received on the wire.
20	type recordedRequest struct {
21		method        string
22		path          string
23		rawQuery      string
24		contentLength int64
25		contentType   string
26		xTrace        string
27		body          []byte
28	}
29	
30	// failoverUpstream is a real TCP HTTP/1.1 server with deterministic,
31	// path-based behaviour that simulates upstream failures at precise points of
32	// the response lifecycle.
33	type failoverUpstream struct {
34		role   string // "first" or "backup"
35		ln     net.Listener
36		mu     sync.Mutex
37		hits   map[string]int
38		record []recordedRequest
39	}
40	
41	func newFailoverUpstream(t *testing.T, role string) *failoverUpstream {
42		t.Helper()
43		u := &failoverUpstream{
44			role: role,
45			hits: make(map[string]int),
46		}
47		ln, err := net.Listen("tcp", "127.0.0.1:0")
48		if err != nil {
49			t.Fatalf("listen for %s upstream: %v", role, err)
50		}
51		u.ln = ln
52		srv := &http.Server{Handler: http.HandlerFunc(u.handle)}
53		go srv.Serve(ln)
54		t.Cleanup(func() { srv.Close(); ln.Close() })
55		return u
56	}
57	
58	func (u *failoverUpstream) addr() string { return u.ln.Addr().String() }
59	
60	func (u *failoverUpstream) hitCount(path string) int {
61		u.mu.Lock()
62		defer u.mu.Unlock()
63		return u.hits[path]
64	}
65	
66	func (u *failoverUpstream) recordings(path string) []recordedRequest {
67		u.mu.Lock()
68		defer u.mu.Unlock()
69		var out []recordedRequest
70		for _, rec := range u.record {
71			if rec.path == path {
72				out = append(out, rec)
73			}
74		}
75		return out
76	}
77	
78	// writeRaw takes over the connection and writes a raw HTTP response, giving
79	// full control over framing (interim responses, truncated chunked bodies).
80	func (u *failoverUpstream) writeRaw(w http.ResponseWriter, lines ...string) net.Conn {
81		conn, rw, err := w.(http.Hijacker).Hijack()
82		if err != nil {
83			panic(err)
84		}
85		for _, l := range lines {
86			fmt.Fprint(rw, l)
87		}
88		rw.Flush()
89		return conn
90	}
91	
92	func (u *failoverUpstream) handle(w http.ResponseWriter, r *http.Request) {
93		u.mu.Lock()
94		u.hits[r.URL.Path]++
95		u.mu.Unlock()
96	
97		if u.role == "first" {
98			switch r.URL.Path {
99			case "/retry-before", "/all-fail":
100				if r.URL.Path == "/all-fail" {
101					// send an interim 103, then drop before any final response
102					conn := u.writeRaw(w,
103						"HTTP/1.1 103 Early Hints\r\n",
104						"Link: </style.css>; rel=preload; as=style\r\n",
105						"\r\n")
106					time.Sleep(20 * time.Millisecond)
107					conn.Close()
108					return
109				}
110				// disconnect before any final (or interim) response header
111				conn := u.writeRaw(w)
112				conn.Close()
113				return
114	
115			case "/retry-info":
116				conn := u.writeRaw(w,
117					"HTTP/1.1 103 Early Hints\r\n",
118					"Link: </style.css>; rel=preload; as=style\r\n",
119					"\r\n")
120				time.Sleep(20 * time.Millisecond)
121				conn.Close() // no final response ever arrives
122				return
123	
124			case "/partial":
125				// full final status + headers, then a chunked body prefix and
126				// an abrupt close without the terminating chunk
127				conn := u.writeRaw(w,
128					"HTTP/1.1 200 OK\r\n",
129					"X-Origin: first\r\n",
130					"Content-Type: text/plain\r\n",
131					"Transfer-Encoding: chunked\r\n",
132					"\r\n",
133					"5\r\npart1\r\n")
134				time.Sleep(20 * time.Millisecond)
135				conn.Close()
136				return
137			}
138		}
139	
140		if u.role == "backup" {
141			switch r.URL.Path {
142			case "/all-fail":
143				conn := u.writeRaw(w,
144					"HTTP/1.1 103 Early Hints\r\n",
145					"Link: </other.css>; rel=preload; as=style\r\n",
146					"\r\n")
147				time.Sleep(20 * time.Millisecond)
148				conn.Close()
149				return
150	
151			case "/retry-before", "/retry-info":
152				body, _ := io.ReadAll(r.Body)
153				u.mu.Lock()
154				u.record = append(u.record, recordedRequest{
155					method:        r.Method,
156					path:          r.URL.Path,
157					rawQuery:      r.URL.RawQuery,
158					contentLength: r.ContentLength,
159					contentType:   r.Header.Get("Content-Type"),
160					xTrace:        r.Header.Get("X-Trace"),
161					body:          body,
162				})
163				u.mu.Unlock()
164	
165				// 201 Created, echoing the request metadata and body back
166				if ct := r.Header.Get("Content-Type"); ct != "" {
167					w.Header().Set("Content-Type", ct)
168				} else {
169					w.Header().Set("Content-Type", "application/json")
170				}
171				if xt := r.Header.Get("X-Trace"); xt != "" {
172					w.Header().Set("X-Trace", xt)
173				}
174				w.WriteHeader(http.StatusCreated)
175				if len(body) > 0 {
176					_, _ = w.Write(body)
177				} else {
178					_, _ = w.Write([]byte(`{"n":1}`))
179				}
180				return
181			}
182		}
183	
184		switch r.URL.Path {
185		case "/ok":
186			_, _ = io.WriteString(w, "ok")
187		case "/empty":
188			w.WriteHeader(http.StatusOK)
189		default:
190			w.WriteHeader(http.StatusNotFound)
191		}
192	}
193	
194	// tracedDo performs a request while recording the interim (1xx) statuses
195	// observed on the client connection, in arrival order, along with the time at
196	// which the first interim status arrived (relative to the request start).
197	func tracedDo(t *testing.T, client *http.Client, req *http.Request) (*http.Response, []int, time.Duration) {
198		t.Helper()
199		var (
200			mu             sync.Mutex
201			interim        []int
202			firstInterimAt time.Duration
203		)
204		start := time.Now()
205		trace := &httptrace.ClientTrace{
206			Got1xxResponse: func(code int, _ textproto.MIMEHeader) error {
207				mu.Lock()
208				if len(interim) == 0 {
209					firstInterimAt = time.Since(start)
210				}
211				interim = append(interim, code)
212				mu.Unlock()
213				return nil
214			},
215		}
216		resp, err := client.Do(req.WithContext(httptrace.WithClientTrace(req.Context(), trace)))
217		if err != nil {
218			t.Fatalf("request %s failed: %v", req.URL.Path, err)
219		}
220		mu.Lock()
221		got := append([]int(nil), interim...)
222		at := firstInterimAt
223		mu.Unlock()
224		return resp, got, at
225	}
226	
227	func newFailoverClient() *http.Client {
228		dialer := &net.Dialer{Timeout: 5 * time.Second}
229		return &http.Client{
230			Timeout: 30 * time.Second,
231			Transport: &http.Transport{
232				DialContext:        dialer.DialContext,
233				DisableCompression: true,
234			},
235		}
236	}
237	
238	// TestReverseProxyFailoverSemantics exercises the requirement that one client
239	// request produces exactly one logical response when a proxy with two
240	// fixed-order upstreams and a one-retry budget fails over.
241	func TestReverseProxyFailoverSemantics(t *testing.T) {
242		first := newFailoverUpstream(t, "first")
243		backup := newFailoverUpstream(t, "backup")
244	
245		tester := caddytest.NewTester(t)
246		tester.InitServer(fmt.Sprintf(`
247		{
248			skip_install_trust
249			admin localhost:2999
250			http_port 9080
251			https_port 9443
252			grace_period 1ns
253		}
254		http://127.0.0.1:9080 {
255			reverse_proxy %s %s {
256				lb_policy first
257				lb_retries 1
258				request_buffers unlimited
259				lb_retry_match {
260					expression `+"`{rp.is_transport_error} == true`"+`
261				}
262			}
263		}
264		`, first.addr(), backup.addr()), "caddyfile")
265	
266		client := newFailoverClient()
267	
268		// 1) POST /retry-before?a=1&b=2: first node dies before any final
269		// header; backup must answer once with 201 and the exact request
270		// metadata, byte sequence and length.
271		t.Run("POST retried before any response", func(t *testing.T) {
272			const body = `{"n":1}`
273			req, err := http.NewRequest(http.MethodPost,
274				"http://127.0.0.1:9080/retry-before?a=1&b=2", strings.NewReader(body))
275			if err != nil {
276				t.Fatal(err)
277			}
278			req.Header.Set("Content-Type", "application/json")
279			req.Header.Set("X-Trace", "t-7")
280	
281			resp, interim, _ := tracedDo(t, client, req)
282			defer resp.Body.Close()
283			gotBody, readErr := io.ReadAll(resp.Body)
284	
285			if len(interim) != 0 {
286				t.Errorf("interim statuses: got %v, want none", interim)
287			}
288			if resp.StatusCode != http.StatusCreated {
289				t.Fatalf("status: got %d, want 201", resp.StatusCode)
290			}
291			if readErr != nil {
292				t.Errorf("reading final body: %v", readErr)
293			}
294			if string(gotBody) != body {
295				t.Errorf("client body: got %q, want %q", gotBody, body)
296			}
297			if resp.Header.Get("Content-Type") != "application/json" {
298				t.Errorf("response Content-Type: got %q, want application/json", resp.Header.Get("Content-Type"))
299			}
300			if resp.Header.Get("X-Trace") != "t-7" {
301				t.Errorf("response X-Trace: got %q, want t-7", resp.Header.Get("X-Trace"))
302			}
303			if resp.ContentLength != int64(len(body)) {
304				t.Errorf("response Content-Length: got %d, want %d", resp.ContentLength, len(body))
305			}
306	
307			// each upstream involved exactly once
308			if got := first.hitCount("/retry-before"); got != 1 {
309				t.Errorf("first upstream hits: got %d, want 1", got)
310			}
311			recs := backup.recordings("/retry-before")
312			if len(recs) != 1 {
313				t.Fatalf("backup upstream received %d requests, want exactly 1", len(recs))
314			}
315			rec := recs[0]
316			if rec.method != http.MethodPost {
317				t.Errorf("backup method: got %q, want POST", rec.method)
318			}
319			if rec.rawQuery != "a=1&b=2" {
320				t.Errorf("backup raw query: got %q, want a=1&b=2", rec.rawQuery)
321			}
322			if rec.contentType != "application/json" {
323				t.Errorf("backup Content-Type: got %q, want application/json", rec.contentType)
324			}
325			if rec.xTrace != "t-7" {
326				t.Errorf("backup X-Trace: got %q, want t-7", rec.xTrace)
327			}
328			if rec.contentLength != int64(len(body)) {
329				t.Errorf("backup Content-Length: got %d, want %d", rec.contentLength, len(body))
330			}
331			if string(rec.body) != body {
332				t.Errorf("backup body: got %q, want %q", rec.body, body)
333			}
334		})
335	
336		// 2) Normal success served by the first node: no failover.
337		t.Run("successful response first node", func(t *testing.T) {
338			resp, interim, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, "http://127.0.0.1:9080/ok"))
339			body, _ := io.ReadAll(resp.Body)
340			resp.Body.Close()
341			if len(interim) != 0 {
342				t.Errorf("interim statuses: got %v, want none", interim)
343			}
344			if resp.StatusCode != http.StatusOK || string(body) != "ok" {
345				t.Fatalf("got %d %q, want 200 ok", resp.StatusCode, body)
346			}
347			if got := backup.hitCount("/ok"); got != 0 {
348				t.Errorf("backup upstream hits for /ok: got %d, want 0", got)
349			}
350		})
351	
352		// 3) Empty body response keeps length/encoding clean.
353		t.Run("empty body response", func(t *testing.T) {
354			resp, _, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, "http://127.0.0.1:9080/empty"))
355			body, readErr := io.ReadAll(resp.Body)
356			resp.Body.Close()
357			if resp.StatusCode != http.StatusOK {
358				t.Fatalf("status: got %d, want 200", resp.StatusCode)
359			}
360			if len(body) != 0 || readErr != nil {
361				t.Fatalf("body: got %q (err=%v), want empty clean body", body, readErr)
362			}
363		})
364	
365		// 4) /retry-info: 103 must arrive, in order and promptly, but is not a
366		// final response; the failover still happens and only the backup's
367		// final response reaches the client.
368		t.Run("103 interim forwarded then retried", func(t *testing.T) {
369			resp, interim, first103At := tracedDo(t, client, mustNewRequest(t, http.MethodGet, "http://127.0.0.1:9080/retry-info"))
370			body, readErr := io.ReadAll(resp.Body)
371			resp.Body.Close()
372	
373			if len(interim) != 1 || interim[0] != http.StatusEarlyHints {
374				t.Fatalf("interim statuses: got %v, want [103]", interim)
375			}
376			// the 103 must have been forwarded promptly (before failover), not
377			// held back until the backup responded
378			if first103At <= 0 || first103At >= 2*time.Second {
379				t.Errorf("103 arrival timing: got %v, want a small positive duration", first103At)
380			}
381			if resp.StatusCode != http.StatusCreated {
382				t.Fatalf("final status: got %d, want 201", resp.StatusCode)
383			}
384			if readErr != nil {
385				t.Errorf("reading final body: %v", readErr)
386			}
387			if string(body) != `{"n":1}` {
388				t.Errorf("final body: got %q, want {\"n\":1}", body)
389			}
390			if got := first.hitCount("/retry-info"); got != 1 {
391				t.Errorf("first upstream hits: got %d, want 1", got)
392			}
393			if got := backup.hitCount("/retry-info"); got != 1 {
394				t.Errorf("backup upstream hits: got %d, want 1", got)
395			}
396		})
397	
398		// 5) /partial: once a final status, headers and body prefix were
399		// produced, there must be no second request and no splicing; the
400		// client keeps what was produced and the transfer ends with an error.
401		t.Run("partial final response is not retried", func(t *testing.T) {
402			resp, interim, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, "http://127.0.0.1:9080/partial"))
403			body, readErr := io.ReadAll(resp.Body)
404			resp.Body.Close()
405	
406			if len(interim) != 0 {
407				t.Errorf("interim statuses: got %v, want none", interim)
408			}
409			if resp.StatusCode != http.StatusOK {
410				t.Fatalf("status: got %d, want 200", resp.StatusCode)
411			}
412			if resp.Header.Get("X-Origin") != "first" {
413				t.Errorf("X-Origin: got %q, want first", resp.Header.Get("X-Origin"))
414			}
415			if !bytes.HasPrefix(body, []byte("part1")) {
416				t.Errorf("body prefix: got %q, want it to start with part1", body)
417			}
418			if readErr == nil {
419				t.Errorf("expected truncated transfer error, got clean read")
420			}
421			if got := first.hitCount("/partial"); got != 1 {
422				t.Errorf("first upstream hits: got %d, want 1", got)
423			}
424			if got := backup.hitCount("/partial"); got != 0 {
425				t.Errorf("backup upstream must not be retried, got %d hits", got)
426			}
427		})
428	
429		// 6) Interleaving requests keeps every request's retry budget, body,
430		// status, length and encoding isolated. Re-run the POST failover after
431		// the other conversations; the backup must again see one full body.
432		t.Run("repeated POST failover stays isolated", func(t *testing.T) {
433			const body = `{"n":1}`
434			req, err := http.NewRequest(http.MethodPost,
435				"http://127.0.0.1:9080/retry-before?a=1&b=2", strings.NewReader(body))
436			if err != nil {
437				t.Fatal(err)
438			}
439			req.Header.Set("Content-Type", "application/json")
440			req.Header.Set("X-Trace", "t-7")
441			resp, interim, _ := tracedDo(t, client, req)
442			gotBody, _ := io.ReadAll(resp.Body)
443			resp.Body.Close()
444	
445			if len(interim) != 0 {
446				t.Errorf("interim statuses: got %v, want none", interim)
447			}
448			if resp.StatusCode != http.StatusCreated || string(gotBody) != body {
449				t.Fatalf("got %d %q, want 201 %q", resp.StatusCode, gotBody, body)
450			}
451			if got := first.hitCount("/retry-before"); got != 2 {
452				t.Errorf("first upstream hits: got %d, want 2 (one per request)", got)
453			}
454			recs := backup.recordings("/retry-before")
455			if len(recs) != 2 {
456				t.Fatalf("backup received %d requests, want 2 (budget reset per request)", len(recs))
457			}
458			for i, rec := range recs {
459				if string(rec.body) != body || rec.contentLength != int64(len(body)) ||
460					rec.rawQuery != "a=1&b=2" || rec.contentType != "application/json" || rec.xTrace != "t-7" {
461					t.Errorf("backup request %d not an exact replay: %+v", i, rec)
462				}
463			}
464		})
465	
466		// 7) Both nodes fail before a final response: single clean 502, no
467		// leftover final headers/body from either failed node, interim
468		// responses already forwarded remain in order.
469		t.Run("both upstreams fail yields single 502 with 103s in order", func(t *testing.T) {
470			resp, interim, first103At := tracedDo(t, client, mustNewRequest(t, http.MethodGet, "http://127.0.0.1:9080/all-fail"))
471			body, readErr := io.ReadAll(resp.Body)
472			resp.Body.Close()
473	
474			if len(interim) != 2 || interim[0] != http.StatusEarlyHints || interim[1] != http.StatusEarlyHints {
475				t.Fatalf("interim statuses: got %v, want [103 103] in order", interim)
476			}
477			// the first interim response must already have been streamed to
478			// the client promptly, before the terminal 502
479			if first103At <= 0 || first103At >= 2*time.Second {
480				t.Errorf("first 103 arrival timing: got %v, want a small positive duration", first103At)
481			}
482			if resp.StatusCode != http.StatusBadGateway {
483				t.Fatalf("final status: got %d, want 502", resp.StatusCode)
484			}
485			if readErr != nil {
486				t.Errorf("502 body should read cleanly: %v", readErr)
487			}
488			if h := resp.Header.Get("X-Origin"); h != "" {
489				t.Errorf("failed node final header X-Origin leaked: %q", h)
490			}
491			if strings.Contains(string(body), "part1") {
492				t.Errorf("502 body contains upstream body fragment: %q", body)
493			}
494			if got := first.hitCount("/all-fail"); got != 1 {
495				t.Errorf("first upstream hits: got %d, want 1", got)
496			}
497			if got := backup.hitCount("/all-fail"); got != 1 {
498				t.Errorf("backup upstream hits: got %d, want 1", got)
499			}
500		})
501	}
502	
503	// TestReverseProxyNoRetrySingleNodeBehaviour verifies that without retries
504	// configured the proxy keeps its original single-node behaviour: a failure is
505	// surfaced immediately, never failing over even though a second healthy
506	// upstream exists elsewhere, while ordinary and truncated responses behave
507	// unchanged.
508	func TestReverseProxyNoRetrySingleNodeBehaviour(t *testing.T) {
509		first := newFailoverUpstream(t, "first")
510		backup := newFailoverUpstream(t, "backup")
511	
512		tester := caddytest.NewTester(t)
513		tester.InitServer(fmt.Sprintf(`
514		{
515			skip_install_trust
516			admin localhost:2999
517			http_port 9082
518			https_port 9445
519			grace_period 1ns
520		}
521		http://127.0.0.1:9082 {
522			reverse_proxy %s
523		}
524		`, first.addr()), "caddyfile")
525	
526		client := newFailoverClient()
527	
528		// success path is untouched
529		resp, _, _ := tracedDo(t, client, mustNewRequest(t, http.MethodGet, "http://127.0.0.1:9082/ok"))
530		body, _ := io.ReadAll(resp.Body)
531		resp.Body.Close()
532		if resp.StatusCode != http.StatusOK || string(body) != "ok" {
533			t.Fatalf("got %d %q, want 200 ok", resp.StatusCode, body)
534		}
535	
536		// disconnect before the response: plain 502, no retry anywhere
537		req, err := http.NewRequest(http.MethodPost,
538			"http://127.0.0.1:9082/retry-before?a=1&b=2", strings.NewReader(`{"n":1}`))
539		if err != nil {
540			t.Fatal(err)
541		}
542		req.Header.Set("Content-Type", "application/json")
543		req.Header.Set("X-Trace", "t-7")
544		resp, _, _ = tracedDo(t, client, req)
545		b502, _ := io.ReadAll(resp.Body)
546		resp.Body.Close()
547		if resp.StatusCode != http.StatusBadGateway {
548			t.Fatalf("status: got %d, want 502", resp.StatusCode)
549		}
550		if bytes.Contains(b502, []byte(`{"n":1}`)) {
551			t.Errorf("502 body must not contain upstream body: %q", b502)
552		}
553		if got := first.hitCount("/retry-before"); got != 1 {
554			t.Errorf("first upstream hits: got %d, want 1 (no retries)", got)
555		}
556		if got := backup.hitCount("/retry-before"); got != 0 {
557			t.Errorf("backup must never be contacted without retry config: got %d hits", got)
558		}
559	
560		// truncated final response still delivered as-is with a transfer error
561		resp, _, _ = tracedDo(t, client, mustNewRequest(t, http.MethodGet, "http://127.0.0.1:9082/partial"))
562		pbody, perr := io.ReadAll(resp.Body)
563		resp.Body.Close()
564		if resp.StatusCode != http.StatusOK || !bytes.HasPrefix(pbody, []byte("part1")) || perr == nil {
565			t.Fatalf("got status=%d body=%q err=%v, want 200 with part1 prefix and transfer error",
566				resp.StatusCode, pbody, perr)
567		}
568		if got := backup.hitCount("/partial"); got != 0 {
569			t.Errorf("backup must never be contacted without retry config: got %d hits", got)
570		}
571	}
572	
573	func mustNewRequest(t *testing.T, method, url string) *http.Request {
574		t.Helper()
575		req, err := http.NewRequest(method, url, nil)
576		if err != nil {
577			t.Fatal(err)
578		}
579		return req
580	}
