			resp, err := tester.Client.Get("http://localhost:9080")
			if err == nil {
				t.Errorf("unexpected response: %d", resp.StatusCode)
			}
		} else {
			tester.AssertGetResponse("http://localhost:9080", 200, tc.expectedBody)
		}
	}
